CREATE TABLE operations.address_quota_buckets (bucket_kind text NOT NULL,subject_hash bytea NOT NULL,window_started_at timestamptz NOT NULL,count integer NOT NULL,expires_at timestamptz NOT NULL,PRIMARY KEY(bucket_kind,subject_hash,window_started_at),CONSTRAINT address_quota_buckets_kind_ck CHECK(bucket_kind IN('metadata_subject_minute','metadata_global_minute','lookup_subject_hour','upstream_minute','upstream_day','canary_minute')),CONSTRAINT address_quota_buckets_hash_ck CHECK(octet_length(subject_hash)=32),CONSTRAINT address_quota_buckets_count_ck CHECK(count BETWEEN 1 AND CASE WHEN bucket_kind='metadata_subject_minute' THEN 20 WHEN bucket_kind='metadata_global_minute' THEN 300 WHEN bucket_kind='lookup_subject_hour' THEN 5 WHEN bucket_kind='upstream_minute' THEN 100 WHEN bucket_kind='upstream_day' THEN 5000 ELSE 5 END),CONSTRAINT address_quota_buckets_expiry_ck CHECK(expires_at>window_started_at AND expires_at<=window_started_at+interval '48 hours'));
CREATE TABLE operations.address_canary_nonces (nonce_hash bytea PRIMARY KEY NOT NULL,key_id text NOT NULL,signature_timestamp timestamptz NOT NULL,expires_at timestamptz NOT NULL,consumed_at timestamptz NOT NULL DEFAULT clock_timestamp(),CONSTRAINT address_canary_nonces_key_id_ck CHECK(length(key_id) BETWEEN 1 AND 128),CONSTRAINT address_canary_nonces_hash_ck CHECK(octet_length(nonce_hash)=32),CONSTRAINT address_canary_nonces_expiry_ck CHECK(expires_at=signature_timestamp+interval '10 minutes' AND expires_at>consumed_at AND expires_at<=consumed_at+interval '48 hours'));
CREATE INDEX address_quota_buckets_expiry_idx ON operations.address_quota_buckets(expires_at);
CREATE INDEX address_canary_nonces_expiry_idx ON operations.address_canary_nonces(expires_at);
